import{_ as a,o as e,c as n,a3 as o}from"./chunks/framework.BlfGB29P.js";const c=JSON.parse('{"title":"Python 与模型基础总览","description":"","frontmatter":{"title":"Python 与模型基础总览"},"headers":[],"relativePath":"py-agent/foundations/index.md","filePath":"py-agent/foundations/index.md","lastUpdated":1785311412000}'),d={name:"py-agent/foundations/index.md"};function i(r,t,h,l,s,p){return e(),n("div",null,[...t[0]||(t[0]=[o('<h1 id="python-与模型基础总览" tabindex="-1">Python 与模型基础总览 <a class="header-anchor" href="#python-与模型基础总览" aria-label="Permalink to &quot;Python 与模型基础总览&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>本模块为没有 Python 或大语言模型经验的读者建立一条完整前置主线：先理解 Python 程序怎样运行、代码怎样组织以及外部数据怎样进入应用，再理解语言模型怎样生成结果，最后完成一个可验证的结构化模型应用。</p><p>这里的 Python 内容是一套面向 Agent 开发的有边界教材。纳入主线的知识必须讲清概念关系、运行机制、API 行为和验证方式；元类、描述符实现、自定义导入器、完整标准库、GUI、数据科学和 C 扩展不在本模块展开。</p><h2 id="目标读者" tabindex="-1">目标读者 <a class="header-anchor" href="#目标读者" aria-label="Permalink to &quot;目标读者&quot;">​</a></h2><p>读者需要具备基本编程思维，但可以没有 Python 开发经验。快速开始只负责建立直观体验，不作为后续知识的替代；Python 新读者应继续按顺序学习语言、工程、异步和模型部分。</p><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><p>完成本模块后，读者应能够：</p><ol><li>用程序结构、对象、名称、类型和可变性解释 Python 程序行为。</li><li>使用容器、函数、模块、类、异常和上下文管理器组织程序。</li><li>建立可复现的项目，并用类型、JSON、Pydantic 和测试约束数据边界。</li><li>解释协程、任务、取消和 HTTP 客户端的生命周期。</li><li>解释 Token、Embedding、Attention、训练、推理和概率生成之间的关系。</li><li>使用模型 API 处理消息、结构化输出、流式事件和失败场景。</li><li>用任务样例判断模型结果是否满足业务要求。</li></ol><h2 id="内容结构" tabindex="-1">内容结构 <a class="header-anchor" href="#内容结构" aria-label="Permalink to &quot;内容结构&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分组</th><th style="text-align:right;">篇数</th><th>阶段结果</th></tr></thead><tbody><tr><td><a href="/py-agent/foundations/quickstart/">快速开始</a></td><td style="text-align:right;">1</td><td>观察一次真实模型调用</td></tr><tr><td><a href="/py-agent/foundations/python-language/">Python 语言基础</a></td><td style="text-align:right;">15</td><td>掌握 Python 的语法、内置数据结构和迭代模型</td></tr><tr><td><a href="/py-agent/foundations/python-abstractions/">Python 抽象与组织</a></td><td style="text-align:right;">7</td><td>理解函数、模块、类和错误边界</td></tr><tr><td><a href="/py-agent/foundations/python-engineering-data/">Python 工程与数据</a></td><td style="text-align:right;">7</td><td>建立可复现、可校验、可测试的项目</td></tr><tr><td><a href="/py-agent/foundations/python-async-http/">Python 异步与 HTTP</a></td><td style="text-align:right;">3</td><td>理解模型客户端依赖的 I/O 机制</td></tr><tr><td><a href="/py-agent/foundations/model-principles/">大语言模型原理</a></td><td style="text-align:right;">7</td><td>理解模型能力的机制与限制</td></tr><tr><td><a href="/py-agent/foundations/model-application/">模型应用基础</a></td><td style="text-align:right;">9</td><td>完成可靠、结构化且可评测的模型应用</td></tr></tbody></table><h2 id="学习路径" tabindex="-1">学习路径 <a class="header-anchor" href="#学习路径" aria-label="Permalink to &quot;学习路径&quot;">​</a></h2><p>Python 新读者可以先完成快速开始建立直观体验，然后按六个后续分组顺序学习。已有 Python 工程经验的读者可以从大语言模型原理开始，但应先确认自己能够解释异步任务、HTTP 生命周期、数据校验和契约测试。</p><h2 id="模块边界" tabindex="-1">模块边界 <a class="header-anchor" href="#模块边界" aria-label="Permalink to &quot;模块边界&quot;">​</a></h2><p>本模块不展开工具调用、MCP、Agent 循环、RAG、记忆和工作流，也不包含 SQL、Redis、服务部署、模型网关和完整可观测平台。这些主题在后续模块中建立在本模块的语言、数据和模型基础之上。</p><h2 id="写作原则" tabindex="-1">写作原则 <a class="header-anchor" href="#写作原则" aria-label="Permalink to &quot;写作原则&quot;">​</a></h2><p>篇数是知识边界拆分后的结果，不是写作指标。每篇文章只承担一个核心问题；概念文章先解释关系与机制，代码只用于观察和验证；教程必须产生可运行结果；基础知识与进阶参考必须清楚分层。</p>',17)])])}const g=a(d,[["render",i]]);export{c as __pageData,g as default};
